-- 39_queue_delegated_decisions.sql
-- Layer: L3 resolved_ -- decisions the BUILDER takes under standing authorisation
--
-- EXECUTED 2026-09-22. Run after 38 and before 35.
--
-- ===========================================================================
-- THE TIERED REVIEW PROTOCOL (ruled 2026-09-22)
-- ===========================================================================
-- The review queue is tiered by the name's total transaction spend:
--   Tier A  >= GBP 10m          per-row USER decision, full evidence protocol (38)
--   Tier B  GBP 100k - < 10m    evidence batches, per-row recommendation, USER
--                               approves each batch (38)
--   Tier C  < GBP 100k          DELEGATED: the builder applies its own
--                               recommendation where the evidence fits an
--                               ESTABLISHED class, and records it HERE
--
-- WHAT A DELEGATED DECISION MAY REST ON
--   accept  -- only the corroboration / payer-records pattern established on the
--              user-decided rows (row 2: the same payer's longer spelling resolves
--              by rule to the same company; row 3: the payer's own award notices
--              state the company number)
--   reject  -- only a STRUCTURAL basis
--   ...and, as the user adopted them: the register's previous names inside their
--   validity window (2026-09-23), and other buyers' awards stating a tier-4
--   candidate's number with none stating another (2026-09-24) -- 04 §8.1
-- Anything novel or ambiguous is escalated to the user, not decided here. New
-- evidence classes are the user's decision, not the builder's.
--
-- WHY FROZEN LITERALS, NOT A RULE THAT RUNS EVERY BUILD
-- A detector that re-ran on each build would silently decide rows that did not
-- exist when the authorisation was given -- an auto-accept by another name. So
-- each delegated decision is computed ONCE, reviewed, and written here as a
-- literal naming the exact company. The stale guard in 35 then treats it exactly
-- like a user decision: it applies only while that company is still the one on
-- offer.
--
-- PRECEDENCE. A user decision on a name ALWAYS overrides a delegated one. A user
-- reversal is recorded in 38, takes effect through the view below, and is a
-- figure-regenerating event.

CREATE OR REPLACE TABLE `portfolio-508106.portfolio_b.resolved_queue_delegated` AS
SELECT *, 'builder (Tier C)' AS decided_by
FROM UNNEST(ARRAY<STRUCT<
  supplier_name_norm       STRING,
  candidate_company_number STRING,
  decision                 STRING,
  decided_on               DATE,
  evidence_class           STRING,
  decision_note            STRING>>[
  -- DELEGATED DECISIONS -- batch 1, 2026-09-22: 55 accepts, class
